/**
 * Every airport the KarinationGroup network touches.
 *
 * Regenerated from the database. The count includes the airports only FORZA
 * and Sonder reach, which is why it is no longer Karination's own 481.
 *
 * Generated from `public.airports`, restricted to the airports that actually
 * appear in the network: either endpoint of a row in `public.flights`, plus
 * every `public.airline_hubs.airport_iata`. The hub union is not redundant —
 * CAH is a declared FORZA hub with no flights filed yet, and it would be
 * missing without it.
 *
 * This is a `.ts` module rather than a `.json` file on purpose: it typechecks
 * as written, it needs no `resolveJsonModule`, and the bundler tree-shakes and
 * minifies it like any other module.
 *
 * Regenerate by re-running the query in the comment below and pasting the rows
 * back in. Do not hand-edit individual rows — the database is the source of
 * truth and a hand-edit will be silently overwritten.
 *
 * ```sql
 * with reachable as (
 *   select origin_iata as iata from public.flights
 *   union select destination_iata from public.flights
 *   union select airport_iata from public.airline_hubs
 * )
 * select a.iata_code, a.airport_name, a.city_name, a.country_code,
 *        round(a.latitude::numeric, 4), round(a.longitude::numeric, 4),
 *        a.timezone, a.utc_offset_minutes
 * from public.airports a
 * join reachable r on r.iata = a.iata_code
 * where a.latitude is not null and a.longitude is not null
 * order by a.iata_code;
 * ```
 *
 * At the time of generation all 608 reachable airports had coordinates, so
 * nothing was skipped. Null text fields would become `''` and a null offset
 * `0`; in practice none of the eight columns was null for any row.
 */

/** One airport, as the map and the timetable need it. */
export interface Airport {
  /** Three-letter IATA code. Unique, and the key everything else joins on. */
  iata: string
  /** Full airport name, e.g. `'Tan Son Nhat International Airport'`. */
  name: string
  /** City the airport serves. Prefer this over `name` in passenger-facing UI. */
  city: string
  /** ISO 3166-1 alpha-2 country code — with one exception, see `regionOf`. */
  country: string
  /** Latitude in degrees, positive north, rounded to 4 decimals (~11 m). */
  lat: number
  /** Longitude in degrees, positive east, rounded to 4 decimals. */
  lon: number
  /** IANA timezone name, e.g. `'Asia/Ho_Chi_Minh'`. */
  tz: string
  /**
   * Fixed UTC offset in minutes, as the database stores it — this is the
   * offset the backend already used to shift arrival times onto the
   * destination's clock. It is not DST-aware. Never re-apply it to a time
   * coming out of the API; those times are already local and already correct.
   */
  offset: number
}

